import type { CSSObject } from '@emotion/react';
import styled from '@emotion/styled';
import { Card, Divider, Heading } from 'components/UI';
import { theme } from 'theme';

interface StyledBigNumberCardProps {
  $hasPin?: boolean;
  $isPinned?: boolean;
}

export const StyledBigNumberCard = styled(Card, {
  shouldForwardProp: (prop) => !['$hasPin', '$isPinned'].includes(prop),
})<StyledBigNumberCardProps>(({ $hasPin, $isPinned }) => ({
  maxHeight: '168px',
  border: '1px solid #e2e2e2',
  boxShadow: 'none !important',
  ...($hasPin && {
    '&:hover': {
      cursor: 'pointer',
      boxShadow: '0px 0px 16px 0px #00000029 !important',
    },
    '&:focus': {
      border: '1px solid #006EDB',
    },
    '&:active': {
      border: '1px solid #006EDB',
    },
  }),
  ...($isPinned && {
    border: '2px solid #006EDB',
  }),
}));

export const StyledBigNumberContainer = styled.div({
  display: 'flex',
  gap: '0.5rem',
  width: '100%',
});

type BigNumberContentGap = 'sm' | 'xs' | 'default';

interface StyledBigNumberContentProps {
  $gap?: BigNumberContentGap;
}

export const StyledBigNumberContent = styled.div<StyledBigNumberContentProps>(
  ({ $gap = 'default' }) => ({
    width: '100%',
    display: 'flex',
    flexDirection: 'column',
    gap: theme.spacing['2'],
    ...($gap === 'sm' && { gap: theme.spacing['1'] }),
    ...($gap === 'xs' && { gap: '2px' }),
    ...($gap === 'default' && { gap: theme.spacing['2'] }),
  }),
);

interface StyledBigNumberLineProps {
  $borderTop?: boolean;
  $marginTop?: 'none' | 'small';
}

export const StyledBigNumberLine = styled.div<StyledBigNumberLineProps>(
  ({ $borderTop, $marginTop }) => ({
    display: 'flex',
    flexDirection: 'row',
    columnGap: theme.spacing['1'],
    alignItems: 'center',
    ...($borderTop === true && { borderTop: '1px solid #1414141F' }),
    ...($borderTop === false && { borderTop: 'none' }),
    ...($marginTop === 'none' && { marginTop: '0px' }),
    ...($marginTop === 'small' && { marginTop: '4px' }),
  }),
);

export const StyledBigNumberTitleSection = styled.div({
  display: 'flex',
  flexDirection: 'column',
  gap: theme.spacing['1'],
});

export const StyledBigNumberTitle = styled(Heading)({
  fontWeight: 'bold',
  height: 'auto',
  fontFamily: theme.fonts.heading,
  color: theme.colors.interfaceLabelPrimary,

  '&.title-color--green': {
    color: theme.colors.charts.txt.status.increase,
  },
  '&.title-color--red': {
    color: theme.colors.charts.txt.status.decrease,
  },
});

type BigNumberTextSize =
  | 'xsmall'
  | 'smallest'
  | 'small'
  | 'medium'
  | 'large';
type BigNumberTextColor = 'gray' | 'green' | 'red' | 'black';
type BigNumberTextWeight = 'light' | 'regular' | 'bold' | 'medium';

const bigNumberTextSizeStyles: Record<BigNumberTextSize, CSSObject> = {
  xsmall: { fontSize: '0.625rem !important' },
  smallest: { fontSize: '0.75rem !important' },
  small: { fontSize: '0.875rem !important' },
  medium: { fontSize: '1rem !important' },
  large: { fontSize: '1.25rem !important' },
};

const bigNumberTextColorStyles: Record<BigNumberTextColor, CSSObject> = {
  gray: { color: theme.colors.interfaceLabelSecondary },
  green: { color: theme.colors.charts.txt.status.increase },
  red: { color: theme.colors.charts.txt.status.decrease },
  black: { color: theme.colors.interfaceLabelPrimary },
};

const bigNumberTextWeightStyles: Record<BigNumberTextWeight, CSSObject> = {
  light: { fontWeight: 'light' },
  regular: { fontWeight: 'regular' },
  bold: { fontWeight: 'bold' },
  medium: { fontWeight: '500' },
};

interface StyledBigNumberTextProps {
  $size?: BigNumberTextSize;
  $color?: BigNumberTextColor;
  $weight?: BigNumberTextWeight;
}

export const StyledBigNumberText = styled.p<StyledBigNumberTextProps>(
  ({ $size, $color, $weight }) => ({
    fontSize: '1rem',
    color: theme.colors.interfaceLabelPrimary,
    margin: 0,
    fontFamily: theme.fonts.paragraph,
    ...($size && bigNumberTextSizeStyles[$size]),
    ...($color && bigNumberTextColorStyles[$color]),
    ...($weight && bigNumberTextWeightStyles[$weight]),
  }),
);

export const StyledBigNumberVariationContainer = styled.span({
  display: 'flex',
  flexDirection: 'column',
  justifyContent: 'space-between',
  height: '80%',
});

export const StyledBigNumberNoDataYet = styled.span({
  width: '100%',
  display: 'flex',
  flexDirection: 'column',
  gap: theme.spacing['2'],
  justifyContent: 'center',
  alignItems: 'center',
});

export const StyledBigNumberDivider = styled(Divider)({
  margin: '0 0.25rem',
});

export const StyledBigNumber = styled.span({
  fontSize: '1.25rem',
  fontWeight: 'bold',
  color: theme.colors.interfaceLabelPrimary,
});
